// Shared test fixture for every test that needs a running MissionNode.
// Each TEST_F gets a fresh node, a fresh MockBackend and a fresh client,
// with the node already configured and activated (state IDLE).

#ifndef MISSION_FIXTURE_HPP_
#define MISSION_FIXTURE_HPP_

#include <gtest/gtest.h>
#include <atomic>
#include <chrono>
#include <functional>
#include <future>
#include <memory>
#include <optional>
#include <thread>
#include "lifecycle_msgs/msg/state.hpp"
#include "positronic_mission/mission_node.hpp"
#include "rclcpp/rclcpp.hpp"
#include "rclcpp_action/rclcpp_action.hpp"
#include "mock_backend.hpp"
#include "positronic_mission/pose_validation.hpp"

namespace positronic_mission
{
namespace test
{

using std::chrono_literals::operator""ms;
using std::chrono_literals::operator""s;
using GoalHandleClient = rclcpp_action::ClientGoalHandle<GoToPose>;
using WrappedResult = GoalHandleClient::WrappedResult;
using PoseStamped = geometry_msgs::msg::PoseStamped;
using LifeState = lifecycle_msgs::msg::State;

class MissionNodeTest : public ::testing::Test
{
protected:
  // ---------- Runs once per test executable ----------
  static void SetUpTestSuite()
  {
    rclcpp::init(0, nullptr);
  }
  static void TearDownTestSuite()
  {
    rclcpp::shutdown();
  }

  // ---------- Runs before EACH test ----------
  void SetUp() override
  {
    // The fake arm. Short motions keep tests fast; tests that need
    // time to cancel/stop mid-motion raise duration_ms themselves.
    mock_ = std::make_shared<MockBackend>();
    mock_->duration_ms = 300;

    node_ = std::make_shared<MissionNode>();
    node_->set_backend(mock_);

    // A plain node that plays the role of "the client"
    client_node_ = std::make_shared<rclcpp::Node>("mission_test_client");
    action_client_ = rclcpp_action::create_client<GoToPose>(client_node_, "/mission/go_to_pose");
    stop_client_ = client_node_->create_client<StateTrigger>("/mission/stop");
    reset_client_ = client_node_->create_client<StateTrigger>("/mission/reset");
    heartbeat_sub_ = client_node_->create_subscription<Heartbeat>(
      "/mission/heartbeat", rclcpp::QoS(10).best_effort(), [this](const Heartbeat::SharedPtr msg) {
        last_state_ = msg->state;
        if (msg->node_name != "mission_node") {
          node_name_ok_ = false;
        }
        const int64_t stamp = rclcpp::Time(msg->stamp).nanoseconds();
        if (stamp <= last_stamp_ns_) {
          last_stamp_ok_ = false;
        }
        last_stamp_ns_ = stamp;
        ++heartbeat_count_;
      });

    // Spin both nodes in a background thread, so the test body can block
    // on futures. The mission node's callbacks stay serialized (default
    // mutually exclusive callback group), like with rclcpp::spin.
    executor_ = std::make_shared<rclcpp::executors::MultiThreadedExecutor>();
    executor_->add_node(node_->get_node_base_interface());
    executor_->add_node(client_node_);
    spin_thread_ = std::thread([this] {
          executor_->spin();
    });

    // Bring the node up: configure -> activate
    ASSERT_EQ(node_->configure().id(), lifecycle_msgs::msg::State::PRIMARY_STATE_INACTIVE);
    ASSERT_EQ(node_->activate().id(), lifecycle_msgs::msg::State::PRIMARY_STATE_ACTIVE);

    ASSERT_TRUE(action_client_->wait_for_action_server(2s));
    ASSERT_TRUE(stop_client_->wait_for_service(2s));
    ASSERT_TRUE(reset_client_->wait_for_service(2s));
    ASSERT_TRUE(wait_for_state(State::IDLE)) << "Never saw an IDLE heartbeat";
  }

  // ---------- Runs after EACH test ----------
  void TearDown() override
  {
    executor_->cancel();
    if (spin_thread_.joinable()) {
      spin_thread_.join();
    }
    if (node_) {
      node_->shutdown();  // stops the backend and joins the execute thread
    }
    action_client_.reset();
    stop_client_.reset();
    reset_client_.reset();
    heartbeat_sub_.reset();
    client_node_.reset();
    node_.reset();
  }

  // ================= Helpers =================

  // A pose that passes validate_pose
  static PoseStamped valid_pose()
  {
    PoseStamped p;
    p.header.frame_id = BASE_FRAME;
    p.pose.position.x = 0.15;
    p.pose.position.z = 0.20;
    p.pose.orientation.w = 1.0;
    return p;
  }

  // Polls `pred` every 10 ms until it's true or `timeout` passes.
  // Use this instead of sleep_for: fast when things work, bounded when they don't.
  static bool wait_until(const std::function<bool()> & pred, std::chrono::milliseconds timeout = 2s)
  {
    const auto end = std::chrono::steady_clock::now() + timeout;
    while (std::chrono::steady_clock::now() < end) {
      if (pred()) {
        return true;
      }
      std::this_thread::sleep_for(10ms);
    }
    return pred();
  }

  // Waits until the heartbeat reports `s`
  bool wait_for_state(State s, std::chrono::milliseconds timeout = 2s)
  {
    return wait_until(
      [this, s] {
        return last_state_.load() == static_cast<uint8_t>(s);
      },
      timeout);
  }

  // Sends a goal. Returns the goal handle, or nullptr if the goal was REJECTED.
  std::shared_ptr<GoalHandleClient> send_goal(const PoseStamped & pose)
  {
    GoToPose::Goal goal;
    goal.target_pose = pose;

    auto options = rclcpp_action::Client<GoToPose>::SendGoalOptions();
    options.feedback_callback =
      [this](GoalHandleClient::SharedPtr, const std::shared_ptr<const GoToPose::Feedback>) {
        ++feedback_count_;
      };

    auto future = action_client_->async_send_goal(goal, options);
    if (future.wait_for(2s) != std::future_status::ready) {
      ADD_FAILURE() << "Timed out waiting for goal response";
      return nullptr;
    }
    return future.get();
  }

  // Waits for the final result of a goal. nullopt on timeout.
  std::optional<WrappedResult> wait_result(
    const std::shared_ptr<GoalHandleClient> & handle, std::chrono::milliseconds timeout = 5s)
  {
    auto future = action_client_->async_get_result(handle);
    if (future.wait_for(timeout) != std::future_status::ready) {
      return std::nullopt;
    }
    return future.get();
  }

  // Requests a cancel. Returns true if the server answered.
  bool cancel_goal(const std::shared_ptr<GoalHandleClient> & handle)
  {
    auto future = action_client_->async_cancel_goal(handle);
    return future.wait_for(2s) == std::future_status::ready;
  }

  // Calls /mission/stop or /mission/reset. nullptr on timeout.
  StateTrigger::Response::SharedPtr call_stop()
  {
    return call_trigger(stop_client_);
  }
  StateTrigger::Response::SharedPtr call_reset()
  {
    return call_trigger(reset_client_);
  }

  StateTrigger::Response::SharedPtr call_trigger(
    const rclcpp::Client<StateTrigger>::SharedPtr & client)
  {
    auto future = client->async_send_request(std::make_shared<StateTrigger::Request>());
    if (future.wait_for(2s) != std::future_status::ready) {
      ADD_FAILURE() << "Timed out waiting for service " << client->get_service_name();
      return nullptr;
    }
    return future.get();
  }

  void cycle(int amount)
  {
    for (int i = 0; i < amount; i++) {
      ASSERT_EQ(node_->deactivate().id(), LifeState::PRIMARY_STATE_INACTIVE);
      ASSERT_EQ(node_->cleanup().id(), LifeState::PRIMARY_STATE_UNCONFIGURED);
      ASSERT_EQ(node_->configure().id(), LifeState::PRIMARY_STATE_INACTIVE);
      ASSERT_EQ(node_->activate().id(), LifeState::PRIMARY_STATE_ACTIVE);
    }
    // Giving time for the client to discover the newaction server
    last_state_ = 255;
    ASSERT_TRUE(action_client_->wait_for_action_server(2s));
    ASSERT_TRUE(wait_for_state(State::IDLE));
  }

  void deactivate_activate_cycle()
  {
    ASSERT_EQ(node_->deactivate().id(), LifeState::PRIMARY_STATE_INACTIVE);
    std::this_thread::sleep_for(100ms);

    // Reseting last state before waiting for a new one.
    last_state_ = 255;
    std::this_thread::sleep_for(300ms);
    EXPECT_EQ(last_state_, 255);

    ASSERT_EQ(node_->activate().id(), LifeState::PRIMARY_STATE_ACTIVE);
  }

  // ================= Members =================
  std::shared_ptr<MockBackend> mock_;
  std::shared_ptr<MissionNode> node_;

  rclcpp::Node::SharedPtr client_node_;
  rclcpp_action::Client<GoToPose>::SharedPtr action_client_;
  rclcpp::Client<StateTrigger>::SharedPtr stop_client_;
  rclcpp::Client<StateTrigger>::SharedPtr reset_client_;
  rclcpp::Subscription<Heartbeat>::SharedPtr heartbeat_sub_;

  std::shared_ptr<rclcpp::executors::MultiThreadedExecutor> executor_;
  std::thread spin_thread_;

  // Written by subscription/feedback callbacks (executor thread), read by tests
  std::atomic<uint8_t> last_state_{255};  // 255 = no heartbeat yet
  std::atomic<bool> node_name_ok_{true};
  std::atomic<bool> last_stamp_ok_{true};
  std::atomic<int64_t> last_stamp_ns_{0};
  std::atomic<int> heartbeat_count_{0};
  std::atomic<int> feedback_count_{0};
};

}  // namespace test
}  // namespace positronic_mission

#endif  // MISSION_FIXTURE_HPP_
